/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_Agent_ChecklistRecord_INSERT
AFTER INSERT ON
tbl_rera_authdesk_agent_checklistaction
FOR EACH ROW
BEGIN      
     Declare v_AgentID BigInt; 
     Declare v_AgentDiaryNumber varchar(100); 
     Declare v_CriteriaCode int;
     Declare v_SubCriteriaCode int;
     Declare v_ChecklistStatus varchar(10);
     
    SET v_AgentID=NEW.Related_Agent_ID;
    SET v_AgentDiaryNumber=NEW.Agent_DiaryNumber;
    SET v_CriteriaCode=NEW.CriteriaCode;
    SET v_SubCriteriaCode=NEW.CriteriaSubCode;
    SET v_ChecklistStatus=NEW.IsChecklistValueOk;

-- Agent Registration Details

-- Profile (Ind/OTI/Authorized Person) Details          
If (v_SubCriteriaCode = 616 or v_SubCriteriaCode = 620 or v_SubCriteriaCode = 621)
then 
   If (v_ChecklistStatus = 'N')
   then
 		update tbl_rera_agent_profile set IsDraft=5	
 		where Agent_ID=v_AgentID
 		and IsActive=1 and IsDraft=1;
   else
 		update tbl_rera_agent_profile set IsDraft=1	
 		where Agent_ID=v_AgentID 
 		and IsActive=1 and IsDraft=5;
   end if;
end if;

-- Other Organization Members 
If (v_SubCriteriaCode = 603)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_othermemberdetail set IsDraft=5	
 	   where Agent_ID=v_AgentID 
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_othermemberdetail set IsDraft=1	
 	   where Agent_ID=v_AgentID  
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;     

-- Agent Payment or Fee Details          
If (v_SubCriteriaCode = 613)
then 
  If (v_ChecklistStatus = 'N')
  then
	   update tbl_rera_agent_payment set IsDraft=5	
	   where Agent_ID=v_AgentID 
	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_payment set IsDraft=1	
  	   where Agent_ID=v_AgentID 
  	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Other State-UT RERA Details          
If (v_SubCriteriaCode = 615)
then 
  If (v_ChecklistStatus = 'N')
  then
	   update tbl_rera_agent_otherstateut_regreradetails set IsDraft=5	
 	   where Agent_ID=v_AgentID 
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_otherstateut_regreradetails set IsDraft=1	
  	   where Agent_ID=v_AgentID 
  	   and IsActive=1 and IsDraft=5;
  end if;
end if;


-- -- ## Document (Renewal-Agent) Details ## --
-- Documents (Place of Bussiness Address Proof)         
If (v_SubCriteriaCode = 606 or v_SubCriteriaCode = 607)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_documents set IsDraft=5	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=402        
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_documents set IsDraft=1	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=402
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Pan Copy (Individual or Organization))         
If (v_SubCriteriaCode = 608)
then 
  If (v_ChecklistStatus = 'N')
  then
	   update tbl_rera_agent_documents set IsDraft=5	
	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode in (403,405)        
	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_documents set IsDraft=1	
  	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode in (403,405)
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Income Tax Return (Year-1 or Year-2 or Year-3))         
If (v_SubCriteriaCode = 609)
then 
  If (v_ChecklistStatus = 'N')
  then
	   update tbl_rera_agent_documents set IsDraft=5	
	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode in (404,411,412)        
	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_documents set IsDraft=1	
  	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode in (404,411,412)
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Company Registration Certificate or Registration By-Law or MOA or AOA)         
If (v_SubCriteriaCode = 614)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_documents set IsDraft=5	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=410        
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_documents set IsDraft=1	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=410
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Permanent Address Proof)         
If (v_SubCriteriaCode = 622)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_documents set IsDraft=5	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=401        
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_documents set IsDraft=1	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=401
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Proforma for Undertaking- cum-Indemnity Bond)         
If (v_SubCriteriaCode = 623)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_documents set IsDraft=5	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=413        
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_documents set IsDraft=1	
 	   where Agent_ID=v_AgentID
       and AgentDoc_InfoCode=413
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

